impl Document {
    pub(crate) fn compare_diagnostic_env_bsw_mode_element(
        &self,
        other: &Document,
        a: &DiagnosticEnvBswModeElement,
        b: &DiagnosticEnvBswModeElement,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_env_mode_element(other, a.base(), b.base(), path)?;
        if a.get_mode_i_ref() != b.get_mode_i_ref() {
            return Err(format!("{path}: MODE_I_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_env_compare_condition(
        &self,
        other: &Document,
        a: &DiagnosticEnvCompareCondition,
        b: &DiagnosticEnvCompareCondition,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_env_condition_formula_part(other, a.base(), b.base(), path)?;
        if a.get_compare_type() != b.get_compare_type() {
            return Err(format!("{path}: COMPARE_TYPE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_env_condition_formula(
        &self,
        other: &Document,
        a: &DiagnosticEnvConditionFormula,
        b: &DiagnosticEnvConditionFormula,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_env_condition_formula_part(other, a.base(), b.base(), path)?;
        if a.get_nrc_value() != b.get_nrc_value() {
            return Err(format!("{path}: NRC_VALUE mismatch"));
        }
        if a.get_op() != b.get_op() {
            return Err(format!("{path}: OP mismatch"));
        }
        let list_a = a.get_parts();
        let list_b = b.get_parts();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: PARTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.PARTS[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_env_condition_formula_part(
        &self,
        _other: &Document,
        a: &DiagnosticEnvConditionFormulaPart,
        b: &DiagnosticEnvConditionFormulaPart,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_diagnostic_env_data_condition(
        &self,
        other: &Document,
        a: &DiagnosticEnvDataCondition,
        b: &DiagnosticEnvDataCondition,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_env_compare_condition(other, a.base(), b.base(), path)?;
        if a.get_compare_value() != b.get_compare_value() {
            return Err(format!("{path}: COMPARE_VALUE mismatch"));
        }
        if a.get_data_element_ref() != b.get_data_element_ref() {
            return Err(format!("{path}: DATA_ELEMENT_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_env_data_element_condition(
        &self,
        other: &Document,
        a: &DiagnosticEnvDataElementCondition,
        b: &DiagnosticEnvDataElementCondition,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_env_compare_condition(other, a.base(), b.base(), path)?;
        if a.get_compare_value() != b.get_compare_value() {
            return Err(format!("{path}: COMPARE_VALUE mismatch"));
        }
        if a.get_data_prototype_i_ref() != b.get_data_prototype_i_ref() {
            return Err(format!("{path}: DATA_PROTOTYPE_I_REF mismatch"));
        }
        if a.get_sw_data_def_props() != b.get_sw_data_def_props() {
            return Err(format!("{path}: SW_DATA_DEF_PROPS mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_env_mode_condition(
        &self,
        _other: &Document,
        a: &DiagnosticEnvModeCondition,
        b: &DiagnosticEnvModeCondition,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_diagnostic_env_mode_element(
        &self,
        other: &Document,
        a: &DiagnosticEnvModeElement,
        b: &DiagnosticEnvModeElement,
        path: &str,
    ) -> Result<(), String> {
        self.compare_referrable(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_diagnostic_env_swc_mode_element(
        &self,
        other: &Document,
        a: &DiagnosticEnvSwcModeElement,
        b: &DiagnosticEnvSwcModeElement,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_env_mode_element(other, a.base(), b.base(), path)?;
        if a.get_mode_i_ref() != b.get_mode_i_ref() {
            return Err(format!("{path}: MODE_I_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_environmental_condition(
        &self,
        other: &Document,
        a: &DiagnosticEnvironmentalCondition,
        b: &DiagnosticEnvironmentalCondition,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_common_element(other, a.base(), b.base(), path)?;
        if a.get_formula() != b.get_formula() {
            return Err(format!("{path}: FORMULA mismatch"));
        }
        let list_a = a.get_mode_elements();
        let list_b = b.get_mode_elements();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MODE_ELEMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.MODE_ELEMENTS[{index}] mismatch"));
            }
        }
        Ok(())
    }
}
